function parseCreatorMetricNumber(value: unknown): number | null {
  if (value === null || value === undefined || value === "") return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

function CreatorQualityScoreBreakdownTooltip({
  breakdown,
  requirementLabel,
  belowThreshold,
  requirementValue,
  creatorValue,
}: {
  breakdown: { score1: number; score2: number; score3: number };
  requirementLabel: string;
  belowThreshold: boolean;
  requirementValue: number;
  creatorValue: number | null;
}) {
  const total = breakdown.score1 + breakdown.score2 + breakdown.score3;
  const creatorDisplay =
    creatorValue !== null ? String(creatorValue) : "—";

  return (
    <div className="space-y-1 text-xs">
      <p className="font-medium">Quality Score</p>
      <p>Score 3: {breakdown.score3} submission{breakdown.score3 === 1 ? "" : "s"}</p>
      <p>Score 2: {breakdown.score2} submission{breakdown.score2 === 1 ? "" : "s"}</p>
      <p>Score 1: {breakdown.score1} submission{breakdown.score1 === 1 ? "" : "s"}</p>
      {total === 0 && (
        <p className="text-muted-foreground">No scored verified submissions yet</p>
      )}
      <p className="pt-1 border-t border-border/50">
        {belowThreshold ? "Below" : "Meets"} required {requirementLabel} (
        {requirementValue}). Creator: {creatorDisplay}
      </p>
    </div>
  );
}

function parseTrustMetricsValue(raw: unknown): Record<string, unknown> | null {
  if (raw && typeof raw === "object") {
    return raw as Record<string, unknown>;
  }
  if (typeof raw === "string") {
    try {
      const parsed = JSON.parse(raw);
      return parsed && typeof parsed === "object" ? parsed : null;
    } catch {
      return null;
    }
  }
  return null;
}

function pickCreatorTrustDataFromSubmissions(submissions: any[]): {
  trust_score: number | null;
  trust_score_metrics: Record<string, unknown> | null;
} {
  for (const submission of submissions) {
    const trustScoreMetrics =
      parseTrustMetricsValue((submission as any)?.trust_score_metrics) ??
      parseTrustMetricsValue(submission?.creator?.trust_score_metrics);
    const rawTrustScore =
      (submission as any)?.trust_score ?? submission?.creator?.trust_score;
    const hasTrustScore =
      rawTrustScore !== null &&
      rawTrustScore !== undefined &&
      rawTrustScore !== "";

    if (trustScoreMetrics || hasTrustScore) {
      const parsedScore = hasTrustScore ? Number(rawTrustScore) : NaN;
      return {
        trust_score: Number.isFinite(parsedScore)
          ? parsedScore
          : trustScoreMetrics?.trust_score !== null &&
              trustScoreMetrics?.trust_score !== undefined
            ? Number(trustScoreMetrics.trust_score)
            : null,
        trust_score_metrics: trustScoreMetrics,
      };
    }
  }

  return { trust_score: null, trust_score_metrics: null };
}

function resolveTrustScoreForDisplay(
  trustMetrics: Record<string, unknown> | null,
  fallbackCounts: {
    total: number;
    verified: number;
    rejected: number;
    pending: number;
  },
): number {
  const storedScore = trustMetrics?.trust_score;
  if (storedScore !== null && storedScore !== undefined && storedScore !== "") {
    const parsed = Number(storedScore);
    if (Number.isFinite(parsed)) return parsed;
  }

  return computeTrustScore(fallbackCounts.verified, fallbackCounts.rejected);
}

function resolveTrustNumberForDisplay(
  trustMetrics: Record<string, unknown> | null,
  fallbackCounts: { verified: number; rejected: number },
): number {
  const storedNumber = trustMetrics?.trust_number;
  if (
    storedNumber !== null &&
    storedNumber !== undefined &&
    storedNumber !== ""
  ) {
    const parsed = Number(storedNumber);
    if (Number.isFinite(parsed)) return parsed;
  }

  return fallbackCounts.verified - fallbackCounts.rejected;
}

// --- Local Type Definitions ---
interface Contest {
  id: string;
  title: string;
  // Moderation status (admin workflow)
  moderation_status:
    | "draft"
    | "pending_approval"
    | "approved"
    | "published"
    | "rejected";
  // Contest lifecycle status (only for published contests)
  status: "upcoming" | "active" | "ended" | "incomplete" | "unknown" | null;
  // Post-contest status for ended campaigns
  post_contest_status?:
    | "pending_review"
    | "in_review"
    | "verification_complete"
    | "payouts_processed"
    | null;
  contest_type?: "leaderboard" | "cpm" | "milestone" | "dual_rewards" | null;
  thumbnail_url?: string | null;
  brief_html?: string | null;
  platform?: string | null;
  start_date: string | null;
  end_date: string | null;
  rules_html?: string | null;
  inspiration_links?: { url: string; description: string }[] | null;
  tracking_links?: { url: string; description: string }[] | null;
  resources?: any | null;
  contest_based_details?: any | null;
  last_metrics_updated?: string | null;
  // New features
  multiple_submissions_enabled?: boolean;
  max_submissions_per_creator?: number;
  max_earnings_per_creator?: number;
  content_type?: string;
  bonus_details?: any;
  // Twitter-specific fields (now stored in contest_based_details.twitter_campaign)
  contest_format?: string | null;
  // Categories, subcategories, and interests
  categories?: string[] | null;
  subcategories?:
    | Array<{ category: string; subcategory: string }>
    | Record<string, string[]>
    | null; // Can be flat array or grouped object format
  interests?: string[] | null;
  // Region data (JSONB format: { "North America": ["United States", "Canada"], ... })
  region?: Record<string, string[]> | null;
  // Payment information
  payment_details?: any | null;
  // Moderation tracking fields
  submitted_for_approval_at?: string | null;
  approved_at?: string | null;
  approved_by?: string | null;
  published_at?: string | null;
  rejection_reason?: string | null;
  payout_adjustment_percentage?: number | null;
  payout_adjustment_mode?: string | null;
  /** Optional campaign minimum creator trust score (0–100). NULL = no requirement. */
  trust_score?: number | null;
  /** Optional campaign minimum trust number (verified − rejected). NULL = no requirement. */
  trust_number?: number | null;
  min_best_quality_score?: number | null;
  min_avg_quality_score?: number | null;
  min_quality_score?: number | null;
  min_platform_earnings?: number | null;
  min_platform_views?: number | null;
}

interface Submission {
  id: string;
  created_at: string;
  content_link: string;
  status:
    | "pending"
    | "verified"
    | "rejected"
    | "paid"
    | "mark_bonus_paid"
    | "mark_both_paid";
  views: number | null;
  other_stats: Record<string, any> | null;
  insights_status?:
    | "ok"
    | "temporary_failure"
    | "permanent_failure"
    | null
    | string;
  last_insights_update?: string | null;
  platform: string | null;
  video_thumbnail_url: string | null;
  video_id?: string | null;
  video_title?: string | null; // For YouTube/Instagram video submissions
  creator_display_name: string | null;
  creator_username: string | null;
  creator_avatar_url: string | null;
  creator_id: string | null;
  // Username coming directly from users table (server-mapped)
  user_username?: string | null;
  earnings?: number | null; // Added for earnings display
  // Twitter-specific fields
  is_twitter_tweet?: boolean; // Flag to identify Twitter tweets
  moderation_status?: "pending" | "verified" | "rejected" | "paid"; // Twitter moderation status
  manual_points_adjustment?: number; // Manual points adjustment for Twitter tweets
  manual_points_reason?: string | null; // Reason for manual points adjustment
  tweet_id?: string; // Twitter tweet ID
  deleted_at?: string | null;
  excluded_by_submission_cap?: boolean;
  // Nested creator object for compatibility
  creator?: {
    id: string | null;
    username: string | null;
    profile_picture_url?: string | null;
    full_name?: string | null;
  };
  // Additional fields that may be present
  paid?: boolean;
  paid_at?: string | null;
  bonus_paid?: boolean;
  bonus_paid_at?: string | null;
  bonus_amount?: number | null;
  quality_score?: number | null;
}
// --- End Local Type Definitions ---

